  ProseChapter(
    'الذهب عبر التاريخ',
    [
      ProseSection(
        'أول ذهب عرفته البشرية',
        'كان الذهب من أوائل المعادن التي عمل بها الإنسان. فهو كثيراً ما '
            'يوجد في الطبيعة بصورته النقية، على هيئة كتل أو رقائق في '
            'الأنهار، ولا حاجة لصهره أولاً من الخام. كان بالإمكان ببساطة '
            'التقاطه وطَرقه.\n\n'
            'أقدم ذهب مشغول معروف يعود إلى مقابر فارنا (Varna) عند البحر '
            'الأسود، نحو أربعة آلاف وخمسمئة سنة قبل التقويم الميلادي. هناك '
            'دُفن أناس مع حُلي ذهبية بديعة الصنع — إشارة مبكرة إلى أن الذهب '
            'كان يدل آنذاك على المكانة والثراء.',
      ),
      ProseSection(
        'أول العملات الذهبية: ليديا وكروسوس',
        'بقي الذهب زمناً طويلاً حُلياً وسبائك لا نقوداً مسكوكة. وقد '
            'تغيّر ذلك في ليديا القديمة، في تركيا الحالية. فهناك سُكّت '
            'أولاً عملات من الإلكتروم، وهو خليط طبيعي من الذهب والفضة.\n\n'
            'تُعدّ عملات الملك كروسوس ملك ليديا أول العملات الذهبية '
            'الخالصة، وهو الملك الذي صار غناه مضرب المثل — فحتى اليوم يُقال '
            '«غني كقارون». ومعه انفصل الذهب المسكوك عن الفضة المسكوكة، '
            'وصارت قيمة العملة تتعلّق بمعدن نقيّ واحد.',
      ),
      ProseSection(
        'بيزنطة والسوليدوس الطويل العمر',
        'سكّت الإمبراطورية الرومانية عملات ذهبية، غير أن عيارها كان '
            'متذبذباً. وكان السوليدوس أكثر ثباتاً، وهو عملة ذهبية أدخلها '
            'الإمبراطور قسطنطين، وحافظت عليها الإمبراطورية الرومانية '
            'الشرقية انطلاقاً من بيزنطة بثبات لافت على مدى عدة قرون، قبل أن '
            'تُخفَّض قيمتها في أواخر العصور الوسطى.\n\n'
            'كان النقد الذي يحافظ على عياره هذه المدة الطويلة إنجازاً '
            'نادراً. وقد قُبِل السوليدوس في نصف منطقة البحر المتوسط بوصفه '
            'نقد تجارة موثوقاً. ويعيش اسمه في كلمة «Sold» (راتب الجندي) وفي '
            'العملة الإيطالية «soldo».',
      ),
      ProseSection(
        'حُمّى الذهب والنقد العالمي',
        'في القرن التاسع عشر أطلقت الاكتشافات الكبرى هجراتٍ حقيقية. ففي '
            'كاليفورنيا، وفي أستراليا، وعند الكلوندايك، انطلق مئات الألوف '
            'ليغسلوا الذهب من الأنهار والجبال. وقد أسست حُمّيات الذهب هذه '
            'مدناً وغيّرت بلداناً بأكملها.\n\n'
            'وفي الوقت نفسه، رسّخت كمية الذهب الجديد دوره بوصفه نقداً '
            'عالمياً. فربطت دول أكثر فأكثر نقودها بالذهب، وصار التبادل بين '
            'البلدان يُحسَب بمقياس مشترك مغطّى بالذهب.',
      ),
      ProseSection(
        'معيار الذهب ونهايته',
        'في معيار الذهب كانت الدولة تَعِد باستبدال نقودها الورقية في أي '
            'وقت بكمية ثابتة من الذهب. وهذا منح النقد مرساةً ثابتة، لكنه '
            'قيّد في الوقت نفسه أيدي الحكومات.\n\n'
            'خطوة فخطوة فُكّت هذه المرساة، وفي عام 1971 انتهت تماماً قابلية '
            'الدولار الأمريكي للاستبدال بالذهب. ومنذ ذلك الحين لم يعد أي '
            'نقد كبير مغطّى بالذهب. أما كيف كان معيار الذهب يعمل بالتفصيل '
            'فمشروح في فصل خاص هو «معيار الذهب ونهايته»؛ أما هنا فلا يهمّ '
