  ProseChapter(
    'الحُلي ومخزن القيمة',
    [
      ProseSection(
        'ثروة تُلبَس',
        'الذهب منذ القِدم ثروةٌ يمكن حملها على الجسد. فالخاتم والقلادة '
            'والسوار حُليٌّ وثروةٌ مدّخرة في آنٍ معاً. ومن يرتدي الذهب '
            'يُظهر يُسره ويحمله معه في الوقت نفسه.\n\n'
            'هذه الطبيعة المزدوجة تجعل الذهب مميزاً. فهو جميل ونافع في آنٍ، '
            'زينةٌ واحتياطٌ في قطعة واحدة. أما مخازن القيمة الأخرى — كبيتٍ '
            'أو حقل — فلا يمكن حملها حول العنق.',
      ),
      ProseSection(
        'المهر وقرش الشدّة',
        'في كثير من الثقافات تكون الحُلي الذهبية هي المهر الذي تجلبه '
            'العروس إلى الزواج. وهي ملكها، وفي وقت الشدّة تكون احتياطها '
            'الخاص. وهكذا يربط الذهب المناسبةَ الاحتفالية بالاحتياط '
