  ProseChapter(
    'نسبة الذهب إلى الفضة عبر آلاف السنين',
    [
      ProseSection(
        'ماذا تقول النسبة أصلاً',
        'تقول نسبة الذهب إلى الفضة كم وحدةً من الفضة تساوي وحدةً واحدةً '
            'من الذهب — عند تساوي الوزن. فإذا كانت النسبة ستة عشر إلى واحد، '
            'فإن الفضة التي توازن قطعةً من الذهب تزن ستة عشر ضعفاً من وزن '
            'قطعة الذهب نفسها. أي أن العدد الأكبر يعني: لقد صارت الفضة أرخص '
            'مقابل الذهب.\n\n'
            'النسبة ليست قيمةً طبيعيةً ثابتة. إنها سعر، والأسعار تتحرك. فقد '
            'انتقل هذا العدد عبر آلاف السنين من قُرب الاثني عشر إلى ما '
            'يتجاوز الستين بكثير. وهذا التنقّل هو ما يُظهره الرسم البياني '
            'في حاسبة القيمة.',
      ),
      ProseSection(
        'العصور القديمة: قُرب الاثني عشر، لكن مع تشتّت',
        'في العصور القديمة كانت النسبة كثيراً ما تقع في نطاق نحو ثمانية '
            'إلى ثلاثة عشر إلى واحد — وغالباً قُرب الاثني عشر، لكنها في '
            'حالات مبكرة منفردة كانت أدنى من ذلك بوضوح. وتوجد في مصر وبابل '
            'واليونان وروما قيم في هذا المقدار. وكل هذه الأعداد مقادير '
            'مقرّبة، لا قيماً مقيسة بدقّة.\n\n'
            'أمّا القول إن النسبة «كانت دائماً اثني عشر فيما مضى» فلا يطابق '
            'ما تدل عليه الشواهد. فالقيم القديمة تشتّتت تشتّتاً كبيراً '
            'تبعاً للمنطقة والزمن، والأدلّة فيها ثغرات. وتاريخ هذه النسبة '
            'عبر آلاف السنين يخصّ هذا الفصل بأكمله؛ والفصول الأخرى تحيل '
            'إليه بدلاً من أن تكرّره.',
      ),
      ProseSection(
        'العصور الوسطى ومطلع العصر الحديث',
        'في العصور الوسطى ومطلع العصر الحديث بقيت النسبة زمناً طويلاً '
