  ProseChapter(
    'الذهب الورقي والذهب المادي',
    [
      ProseSection(
        'حيازة المعدن أو حيازة المطالبة',
        'هناك طريقتان مختلفتان جذرياً لامتلاك الذهب. فإمّا أن تحوز '
            'المعدن نفسه — سبائك أو عملات في يدك أو في الخزينة — وإمّا أن '
