  ProseChapter(
    'هل ينبغي أن تعود النقود إلى الذهب؟',
    [
      ProseSection(
        'الحجة المؤيدة للربط',
        'من يؤيّد ربط النقود بالذهب يقدّر قبل كل شيء الانضباط. فإذا '
            'كانت النقود مربوطةً بمخزون من الذهب، لم يستطع الدولة أن تزيدها '
            'كما تشاء. ويُفترض أن يقي ذلك من التضخم وأن يمنح النقود مرساةً '
            'ثابتة.\n\n'
            'كذلك يشهد الثبات الطويل، في نظر هؤلاء، لصالح الذهب: فعلى مدى '
            'أزمنة طويلة جداً حافظ على قوته الشرائية على وجه التقريب، كما '
            'يبيّن الفصل المتعلق بالحبوب. فالنقود المرساة على هذا النحو، في '
            'رأيهم، أصدق من نقودٍ يمكن زيادتها.',
      ),
      ProseSection(
        'الحجة المعارضة',
        'أمّا الطرف الآخر فيرى الربط جموداً خطيراً. فإذا كانت كمية '
            'النقود مكبّلةً بالذهب، لم تستطع الحكومة في أزمةٍ أن تتدارك '
            'الأمر. وهذا تحديداً ما يُحمّله كثيرون مسؤولية عمق الأزمة '
            'الاقتصادية الكبرى حوالي عام 1930 — إذ بقيت النقود شحيحة في '
            'وقتٍ كان لا بدّ أن تزداد فيه.\n\n'
            'يُضاف إلى ذلك أن النظام المربوط بالذهب يميل إلى الانكماش: فإذا '
            'نما الاقتصاد أسرع من مخزون الذهب، وجب أن تنخفض الأسعار. '
            'والأسعار الهابطة تبدو حسنة في الظاهر، لكنها كثيراً ما تشلّ '
            'الإنفاق والتشغيل.',
      ),
      ProseSection(
        'لماذا لم يعد أيّ بلد كبير',
        'رغم كل المؤيّدين، لم يعد أيّ بلد كبير إلى معيار الذهب. وإذا '
            'سُئل خبراء الاقتصاد، رفضت الأغلبية العودة إليه.\n\n'
            'والسبب العملي هو المرونة: فالدول اليوم تريد أن تستطيع التحكّم '
            'في كمية نقودها لتلطيف الأزمات. وربطُ النقود بالذهب يضيّق هذا '
